import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 조회 범위 값과 페이지 크기 기본값·최대값
const SCOPES = ['전체', '부서', '개인'];
const STATUSES = ['재직자', '퇴직자'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function textOf(v: unknown): string {
  if (typeof v === 'string') {
    return v.trim();
  }
  if (typeof v === 'number') {
    return String(v);
  }
  return '';
}

@Controller('api/v1')
export class FnSfr01905Controller {
  @Get('/annual-leaves/summary')
  async listAnnualLeaveSummaries(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const query = checks.queryOf(req.query);

    // 가정: 근태 담당자 역할이 없는 임직원은 조회 범위와 관계없이 본인 연차만 본다
    let isManager = true;
    try {
      user.require('근태 담당자');
    } catch (e) {
      isManager = false;
    }

    const scope = textOf(query['scope']);
    const departmentId = textOf(query['departmentId']);
    if (!SCOPES.includes(scope)) {
      throw new ApiError(422, 'INVALID_LEAVE_SCOPE', '조회 범위는 전체, 부서, 개인 중 하나여야 합니다.');
    }
    if (scope === '부서' && departmentId === '') {
      throw new ApiError(422, 'INVALID_LEAVE_SCOPE', '부서 범위로 조회하려면 부서를 선택해야 합니다.');
    }

    const baseYear = textOf(query['baseYear']);
    if (!/^\d{4}$/.test(baseYear)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '기준연도는 4자리 숫자로 입력해야 합니다.');
    }
    if (departmentId !== '' && !/^\d+$/.test(departmentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '부서 값이 올바르지 않습니다.');
    }
    const employmentStatus = textOf(query['employmentStatus']);
    if (employmentStatus !== '' && !STATUSES.includes(employmentStatus)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '재직 구분은 재직자 또는 퇴직자여야 합니다.');
    }
    const pageText = textOf(query['page']);
    const sizeText = textOf(query['size']);
    if (pageText !== '' && !/^\d+$/.test(pageText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
    }
    if (sizeText !== '' && !/^[1-9]\d*$/.test(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 크기 값이 올바르지 않습니다.');
    }
    const page = pageText === '' ? 0 : Number(pageText);
    const size = Math.min(sizeText === '' ? DEFAULT_SIZE : Number(sizeText), MAX_SIZE);

    return transaction(async (db) => {
      const params: Record<string, unknown> = { baseYear };
      const conditions: string[] = [];
      if (!isManager || scope === '개인') {
        conditions.push('e.employee_id = CAST(:userId AS bigint)');
        params['userId'] = user.id;
      } else if (scope === '부서') {
        conditions.push('e.department_id = CAST(:departmentId AS bigint)');
        params['departmentId'] = departmentId;
      }
      if (employmentStatus !== '') {
        conditions.push('e.employment_status = :employmentStatus');
        params['employmentStatus'] = employmentStatus;
      }
      const where = conditions.length > 0 ? ' WHERE ' + conditions.join(' AND ') : '';
      const from =
        ' FROM employee e' +
        ' JOIN department d ON d.department_id = e.department_id' +
        ' JOIN annual_leave al ON al.employee_id = e.employee_id' +
        ' AND al.base_year = CAST(:baseYear AS integer)';

      const countRows = await db.query('SELECT COUNT(*) AS "total"' + from + where, params);
      const total = Number(countRows[0]?.['total'] ?? 0);

      // 월별 사용 연차: 승인된 근태에 연결된 사용 내역을 사용일의 월별로 합산
      const monthly =
        '(SELECT COALESCE(json_agg(json_build_object(\'month\', m.month, \'usedDays\', m.days) ORDER BY m.month), \'[]\'::json)' +
        ' FROM (SELECT CAST(EXTRACT(MONTH FROM lu.used_date) AS integer) AS month, CAST(SUM(lu.used_days) AS numeric) AS days' +
        ' FROM leave_usage lu' +
        ' JOIN attendance_request ar ON ar.attendance_request_id = lu.attendance_request_id' +
        ' WHERE lu.annual_leave_id = al.annual_leave_id AND ar.approval_status = \'승인\'' +
        ' GROUP BY 1) m) AS "monthlyUsedDays"';

      const selectSql =
        'SELECT e.employee_no AS "employeeNo",' +
        ' e.name AS "employeeName",' +
        ' d.name AS "departmentName",' +
        ' CAST(al.granted_days AS float8) AS "grantedDays",' +
        ' CAST(COALESCE(al.used_days, 0) AS float8) AS "usedDays",' +
        ' CAST(COALESCE(al.remaining_days, al.granted_days) AS float8) AS "remainingDays",' +
        ' ' + monthly +
        from + where +
        ' ORDER BY e.employee_no' +
        ' LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)';
      const items = await db.query(selectSql, { ...params, limit: size, offset: page * size });

      return { items, page, size, total };
    });
  }
}

