import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  Select,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

interface Applied {
  scope: string;
  baseYear: number | string;
  departmentId: number | string;
  employmentStatus: string;
}

export default function FnSfr01905Page({ role }: PageProps) {
  const initial: Applied = {
    scope: '개인',
    baseYear: new Date().getFullYear(),
    departmentId: '',
    employmentStatus: '',
  };
  const [form, setForm] = useState<Applied>(initial);
  const [applied, setApplied] = useState<Applied>(initial);
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page>(
    () =>
      call<Page>('GET', '/annual-leaves/summary', role, undefined, {
        scope: applied.scope,
        baseYear: applied.baseYear,
        departmentId: applied.scope === '부서' ? applied.departmentId : '',
        employmentStatus: applied.employmentStatus,
        page,
        size: SIZE,
      }),
    [applied, page],
  );

  function search() {
    if (form.baseYear === '' || !/^\d{4}$/.test(String(form.baseYear))) {
      setFormError('기준연도를 4자리 숫자로 입력해 주세요.');
      return;
    }
    if (form.scope === '부서' && form.departmentId === '') {
      setFormError('부서 범위로 조회하려면 부서를 선택해 주세요.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied(form);
  }

  function reset() {
    setFormError('');
    setForm(initial);
    setPage(0);
    setApplied(initial);
  }

  if (selected) {
    const months = Array.isArray(selected['monthlyUsedDays'])
      ? (selected['monthlyUsedDays'] as Row[])
      : [];
    const monthRows: Row[] = [];
    for (let m = 1; m <= 12; m += 1) {
      const found = months.find((x) => Number(x['month']) === m);
      monthRows.push({ month: m + '월', usedDays: found ? found['usedDays'] : 0 });
    }
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>
          목록으로 돌아가기
        </button>
        <section className="box">
          <h2>연차 총괄현황</h2>
          <Pairs
            items={[
              ['사번', String(selected['employeeNo'] ?? '')],
              ['임직원명', String(selected['employeeName'] ?? '')],
              ['부서명', String(selected['departmentName'] ?? '')],
              ['생성일수', <Num value={selected['grantedDays']} />],
              ['사용일수', <Num value={selected['usedDays']} />],
              ['잔여일수', <Num value={selected['remainingDays']} />],
            ]}
          />
        </section>
        <section className="box">
          <h2>월별 사용 연차</h2>
          <DataTable
            columns={[
              { key: 'month', label: '월' },
              { key: 'usedDays', label: '사용 연차 일수', render: (r) => <Num value={r['usedDays']} /> },
            ]}
            rows={monthRows}
          />
        </section>
      </div>
    );
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>연차 총괄현황 및 월별 사용 연차</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 범위" required>
            <Select
              value={form.scope}
              onChange={(v) => setForm({ ...form, scope: v, departmentId: '' })}
              options={[
                ['전체', '전체'],
                ['부서', '부서'],
                ['개인', '개인'],
              ]}
              placeholder="선택"
            />
          </Field>
          <Field label="기준연도" required>
            <NumberInput value={form.baseYear} onChange={(v) => setForm({ ...form, baseYear: v })} />
          </Field>
          {form.scope === '부서' ? (
            <Field label="부서" required>
              <LookupSelect
                table="department"
                role={role}
                value={form.departmentId}
                onChange={(v) => setForm({ ...form, departmentId: v })}
                placeholder="부서 선택"
              />
            </Field>
          ) : null}
          <Field label="재직 구분">
            <Select
              value={form.employmentStatus}
              onChange={(v) => setForm({ ...form, employmentStatus: v })}
              options={[
                ['재직자', '재직자'],
                ['퇴직자', '퇴직자'],
              ]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total} />
        <DataTable
          columns={[
            {
              key: 'employeeName',
              label: '임직원명',
              render: (r) => String(r['employeeName'] ?? '') + ' (' + String(r['employeeNo'] ?? '') + ')',
            },
            { key: 'departmentName', label: '부서명' },
            { key: 'grantedDays', label: '생성일수', render: (r) => <Num value={r['grantedDays']} /> },
            { key: 'usedDays', label: '사용일수', render: (r) => <Num value={r['usedDays']} /> },
            { key: 'remainingDays', label: '잔여일수', render: (r) => <Num value={r['remainingDays']} /> },
          ]}
          rows={data?.items ?? []}
          onRowClick={(row) => setSelected(row)}
          empty={loading ? '불러오는 중입니다.' : '조회 결과가 없습니다. 조회 범위와 기준연도를 바꿔 다시 조회해 보세요.'}
        />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
    </div>
  );
}
